import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Быстрый старт","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/quick-start.md","filePath":"ru/guides/quick-start.md","lastUpdated":1792323081000}'),s={name:"ru/guides/quick-start.md"};function n(l,t,i,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="быстрыи-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#быстрыи-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h1><p>Полное руководство с нуля: установите приложение, войдите, создайте первого Bot, поручите ему настоящую работу и свяжитесь с ним из чат-платформы. Это займёт около пятнадцати минут.</p><h2 id="что-понадобится" tabindex="-1">Что понадобится <a class="header-anchor" href="#что-понадобится" aria-label="Permalink to &quot;Что понадобится&quot;">​</a></h2><ul><li>Компьютер с macOS, Windows или Linux.</li><li>Аккаунт <a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> — его можно создать прямо при входе.</li></ul><p>Это всё. В Memoh Cloud уже есть размещённые модели (DeepSeek, Kimi, GPT, Claude и другие), так что API-ключ для старта не нужен.</p><h2 id="шаг-1-установите-memoh" tabindex="-1">Шаг 1: установите Memoh <a class="header-anchor" href="#шаг-1-установите-memoh" aria-label="Permalink to &quot;Шаг 1: установите Memoh&quot;">​</a></h2><p>Скачайте приложение для своей платформы со <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">страницы загрузки</a> — macOS (DMG), Windows (установщик) или Linux (AppImage/deb/rpm) — и откройте его.</p><h2 id="шаг-2-воидите" tabindex="-1">Шаг 2: войдите <a class="header-anchor" href="#шаг-2-воидите" aria-label="Permalink to &quot;Шаг 2: войдите&quot;">​</a></h2><p>На экране подключения выберите <strong>Memoh Cloud</strong> и войдите или создайте аккаунт.</p><h2 id="шаг-3-создаите-первого-bot" tabindex="-1">Шаг 3: создайте первого Bot <a class="header-anchor" href="#шаг-3-создаите-первого-bot" aria-label="Permalink to &quot;Шаг 3: создайте первого Bot&quot;">​</a></h2><p>Откройте <strong>Bots → New Bot</strong>, укажите имя и отображаемое имя, затем выберите модель чата на вкладке <strong>General</strong>. Размещённые модели готовы к работе.</p><p>Теперь напишите его инструкции. Это самый важный шаг, и именно здесь чаще всего ошибаются — как правило, формулируя слишком расплывчато. Ясно опишите одну задачу:</p><blockquote><p><strong>Имя:</strong> Digest</p><p><strong>Роль:</strong> еженедельный дайджест чтения</p><p><strong>Инструкции:</strong> собирай статьи, которые я отправляю тебе в течение недели. Каждую пятницу готовь дайджест, сгруппированный по темам: одно предложение на статью с её исходной ссылкой, в конце — раздел «стоит перечитать». Исходные ссылки не меняй. Никогда ничего не публикуй открыто.</p></blockquote><p>Bot с одной чёткой задачей накапливает куда больше полезного контекста, чем Bot, который делает всё подряд. Когда работа действительно распадается на отдельные роли, создайте ещё один Bot вместо того, чтобы перегружать этот: у каждого Bot свои рабочее пространство, память и конфигурация. Разбор каждой вкладки — на странице <a href="./working-with-bots.html">Bot</a>.</p><p>Нажмите <strong>Chat</strong> и поздоровайтесь. Ответ подтверждает, что путь к модели работает.</p><h2 id="собственные-модели-byok" tabindex="-1">Собственные модели (BYOK) <a class="header-anchor" href="#собственные-модели-byok" aria-label="Permalink to &quot;Собственные модели (BYOK)&quot;">​</a></h2><p>Помимо размещённых моделей, вы в любой момент можете подключить собственные (Bring Your Own Key):</p><ol><li>Откройте <strong>Providers</strong> в боковой панели и нажмите <strong>Add Provider</strong>.</li><li>Выберите шаблон (OpenAI, Anthropic, Gemini, DeepSeek, Zhipu, OpenRouter, Ollama и другие) и вставьте свой API-ключ; для OpenAI-совместимых эндпоинтов укажите также базовый URL.</li><li>Откройте провайдера и <strong>синхронизируйте</strong> список его моделей или добавьте хотя бы одну модель чата вручную, затем переключитесь на неё на вкладке <strong>General</strong> нужного Bot.</li></ol><p>Использование BYOK тарифицирует ваш провайдер по собственным расценкам. Та же идея работает для агентов для программирования: на вкладке <strong>Agent</strong> нужного Bot войдите в Claude Code или Codex со своей подпиской или API-ключом. Поля и примечания по конкретным провайдерам — в <a href="./../integrations/providers/llm.html">Провайдерах моделей</a>.</p><h2 id="шаг-4-даите-ему-задачу" tabindex="-1">Шаг 4: дайте ему задачу <a class="header-anchor" href="#шаг-4-даите-ему-задачу" aria-label="Permalink to &quot;Шаг 4: дайте ему задачу&quot;">​</a></h2><p>Хороший первый запрос отвечает на пять вопросов:</p><table tabindex="0"><thead><tr><th>Элемент</th><th>На какой вопрос он отвечает</th></tr></thead><tbody><tr><td><strong>Результат</strong></td><td>Что должно существовать, когда работа закончена?</td></tr><tr><td><strong>Источник</strong></td><td>Какие файлы, сайты или диалоги относятся к делу?</td></tr><tr><td><strong>Ограничения</strong></td><td>Чего нельзя касаться и что требует вашего подтверждения?</td></tr><tr><td><strong>Формат</strong></td><td>В каком виде должен быть доставлен ответ?</td></tr><tr><td><strong>Контрольная точка</strong></td><td>Когда ему остановиться и свериться с вами?</td></tr></tbody></table><p>Чтобы получить результат за несколько минут и без входа в какие-либо внешние сервисы, загрузите документ и попробуйте:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Сделай из этого документа выжимку в пять ключевых пунктов. Отдельным разделом</span></span>
<span class="line"><span>перечисли все даты, решения и открытые вопросы, указывая, с какой страницы или</span></span>
<span class="line"><span>из какого раздела взят каждый пункт. Исходный файл не изменяй.</span></span></code></pre></div><p>Bot читает файл в собственном рабочем пространстве и пишет результат обратно в диалог. Всё, что он создаёт, остаётся в рабочем пространстве — просматривать и редактировать это можно в разделе <a href="./files.html">Файлы</a>.</p><h2 id="шаг-5-даите-ему-рабочее-пространство-и-браузер" tabindex="-1">Шаг 5: дайте ему рабочее пространство и браузер <a class="header-anchor" href="#шаг-5-даите-ему-рабочее-пространство-и-браузер" aria-label="Permalink to &quot;Шаг 5: дайте ему рабочее пространство и браузер&quot;">​</a></h2><p>Рабочее пространство — это место, где Bot выполняет работу. В нём есть файловая система Linux, терминал и предустановленный набор инструментов (Python, Node.js, uv, npm), так что очистку данных, скрипты и сборки он запускает напрямую:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Удали из CSV, который я только что загрузил, все строки с пустой колонкой email.</span></span>
<span class="line"><span>Отдай мне очищенный файл и скажи, сколько строк ты удалил.</span></span></code></pre></div><p>Когда задаче нужен настоящий браузер — сайт, который ломается в безголовом режиме, или страница за формой входа, — включите видимый рабочий стол на вкладке <strong>Desktop</strong> нужного Bot. После запуска Bot управляет Chrome с графическим интерфейсом (headed), и вы можете наблюдать за его работой в панели рабочего стола.</p><p>Когда он упирается в стену входа, перехватите экран сами: введите пароль, passkey или одноразовый код, затем верните управление. Сессия браузера остаётся в этом рабочем пространстве, поэтому последующие задачи не требуют повторного входа.</p><div class="warning custom-block"><p class="custom-block-title">Выдавайте доступ осознанно</p><p>Доступ к рабочему пространству разделён на уровни: только чат, чтение файлов, запись файлов, выполнение команд и управление контейнером. Давайте уровень, которого требует задача, и не больше. См. <a href="./access.html">Контроль доступа</a>.</p></div><p>Подробности — в разделах <a href="./container.html">Рабочее пространство</a> и <a href="./browser-computer-use.html">Browser / Computer Use</a>.</p><h2 id="шаг-6-свяжитесь-с-ним-из-чат-платформы" tabindex="-1">Шаг 6: свяжитесь с ним из чат-платформы <a class="header-anchor" href="#шаг-6-свяжитесь-с-ним-из-чат-платформы" aria-label="Permalink to &quot;Шаг 6: свяжитесь с ним из чат-платформы&quot;">​</a></h2><p>Bot полезнее всего там, где вы и так общаетесь.</p><ol><li>Откройте вкладку <strong>Platforms</strong> нужного Bot и нажмите <strong>Add</strong>.</li><li>Выберите платформу — Telegram, Slack, Discord, Feishu, DingTalk, WeCom, WeChat, QQ или LINE — и вставьте учётные данные этой платформы.</li><li>Напишите ему из этой платформы. Первое сообщение создаёт сессию; отправьте <code>/help</code>, чтобы увидеть доступные <a href="./slash-commands.html">слэш-команды</a>.</li></ol><p>С этого момента вы можете поручить задачу с телефона и забрать результат в том же диалоге. Настройка по платформам — в <a href="./../integrations/channels/">Каналах</a>.</p><h2 id="шаг-7-проверьте-результат-и-закрепите-правила" tabindex="-1">Шаг 7: проверьте результат и закрепите правила <a class="header-anchor" href="#шаг-7-проверьте-результат-и-закрепите-правила" aria-label="Permalink to &quot;Шаг 7: проверьте результат и закрепите правила&quot;">​</a></h2><p>Когда что-то не так, скажите об этом. Формулируйте исправления как долговременные правила, а не разовые поправки:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Для всех будущих дайджестов используй такой формат: группировка по темам,</span></span>
<span class="line"><span>одна строка на статью, ссылки внутри строк, в конце — раздел «стоит перечитать».</span></span></code></pre></div><p>Когда рутина устоялась, перестаньте набирать её заново:</p><ul><li>Сохраните её как <a href="./skills.html">навык</a>, чтобы одна фраза запускала весь порядок действий.</li><li>Превратите её в <a href="./schedule.html">задачу по расписанию</a>, которая выполняется по cron вообще без чата.</li><li>Используйте <a href="./memory.html">долговременную память</a>, чтобы переносить ваши предпочтения и контекст проекта в каждую будущую сессию.</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Цель</th><th>Что читать</th></tr></thead><tbody><tr><td>Настроить Bot вкладка за вкладкой</td><td><a href="./working-with-bots.html">Bot</a></td></tr><tr><td>Разобраться в chat, discuss и маршрутизации</td><td><a href="./sessions.html">Сессии</a></td></tr><tr><td>Запускать задачи по расписанию и повторяющуюся работу</td><td><a href="./schedule.html">Задачи по расписанию</a></td></tr><tr><td>Подключить внешние инструменты и данные</td><td><a href="./mcp.html">MCP</a>, <a href="./../self-hosted/connectors.html">Коннекторы</a></td></tr><tr><td>Установить готовые возможности</td><td><a href="./supermarket.html">Supermarket</a></td></tr><tr><td>Встроиться в события жизненного цикла</td><td><a href="./hooks.html">Hooks</a></td></tr><tr><td>Управлять тем, кто может говорить с Bot</td><td><a href="./access.html">Контроль доступа</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Нужна помощь?</p><p>Вопросы о тарифах, кредитах или вашем аккаунте — и всё, чего не покрывает этот сайт, — разбираются в <a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Центре помощи</a>; там же можно связаться с командой Memoh.</p></div>`,44)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
